int solution(int temps[], int temps_len, int safe, int need) {
    int answer = -1;
    int ice = 0;
    int streak = 0;
    for (int i = 0; i < temps_len; i++) {
        if (temps[i] < 0) {
            ice += -temps[i];
        } else if (temps[i] > 0) {
            ice -= temps[i] * 2;
            if (ice < 0) {
                ice = 0;
            }
        }
        if (ice >= safe) {
            streak++;
        } else {
            streak = 0;
        }
        if (streak == need) {
            answer = i + 1;
            break;
        }
    }
    return answer;
}

