#include <stdio.h>

int solution(int gain[], int gain_len, int goal, int need, int inc) {
    int answer = 0;
    int level = 1;
    int xp = 0;
    while (level < goal) {
        answer++;
        xp += gain[(answer - 1) % gain_len];
        while (xp >= need) {
            xp -= need;
            level++;
            need += inc;
        }
    }
    return answer;
}

